{"rob": "robolang 1.3;

task carry_and_hold(robot r, object obj, location src, location dst, sensor cam) {
    goal { holding r obj; robot_at r dst; }
    plan {
        move r to src;
        grasp r obj;
        move r to dst;
        inspect r obj using cam;
    }
}
